preConditionHook:
// EL: rh = highest(h, rangeBars)[lag]; rl = lowest(l, rangeBars)[lag] --
// the rangeBars-bar block ending at the signal bar, i.e. bars lag..lag+rangeBars-1.
// EL highest/lowest bottom out in Extremes(), which is EL SOURCE: seeded at
// the first bar of the window, scanning the rest with a strict,
// tolerance-carrying comparison. So the loop below seeds first and uses
// el_gt/el_lt for the scan (see Breakout and CloseAbovePriorHighestHigh).
rh = high[lag];
rl = low[lag];
for (int i = 1; i < (int)rangeBars; ++i) {
    if (el_gt(high[(int)lag + i], rh)) rh = high[(int)lag + i];
    if (el_lt(low[(int)lag + i], rl)) rl = low[(int)lag + i];
}
// The epsilon guards a zero-width block: EL raises a runtime divide-by-zero
// error on a zero denominator (EL_FEATURES.md).
pos = ((high[lag] + low[lag]) / 2 - rl) / (rh - rl + epsilon);
